cd /filesystem && mkdir -p /tmp/txt && for f in $(find . -name "*.pdf"); do out="/tmp/txt/$(echo $f | sed 's|^\./||; s|/|__|g').txt"; pdftotext -layout "$f" "$out"; done; for f in $(find . -name "*.docx"); do out="/tmp/txt/$(echo $f | sed 's|^\./||; s|/|__|g').txt"; pandoc -t plain --wrap=none "$f" -o "$out"; done; for f in $(find . -name "*.txt" -o -name "*.eml"); do out="/tmp/txt/$(echo $f | sed 's|^\./||; s|/|__|g').txt"; cp "$f" "$out"; done; python3 - <<'EOF'
import openpyxl, glob, os
for f in glob.glob('/filesystem/**/*.xlsx', recursive=True):
    rel = os.path.relpath(f, '/filesystem').replace('/','__')
    out = open('/tmp/txt/'+rel+'.txt','w')
    wb = openpyxl.load_workbook(f)
    for ws in wb.worksheets:
        out.write(f'=== SHEET: {ws.title} {ws.dimensions} state={ws.sheet_state}\n')
        for row in ws.iter_rows():
            vals = [c.value for c in row]
            if any(v is not None for v in vals):
                out.write(repr(vals)+'\n')
        for row in ws.iter_rows():
            for c in row:
                if c.comment:
                    out.write(f'COMMENT {c.coordinate}: {c.comment.text}\n')
    out.close()
EOF
